function incrementDecimalString(numStr) {
  const digits = numStr.split('')
  let carry = 1
  for (let i = digits.length - 1; i >= 0 && carry; i--) {
    const sum = Number(digits[i]) + carry
    if (sum >= 10) {
      digits[i] = '0'
      carry = 1
    } else {
      digits[i] = String(sum)
      carry = 0
