/**
 * 房屋坐落格式化（bug6677）：按行字段重建「项目名+幢-单元-室号」。
 * 不依赖后端拼接串 position，历史数据同样带分隔符。
 * 空值用显式判断跳过（不用 filter(Boolean)：会丢弃数字 0）。
 * @param {object} row 表格行数据
 * @param {object} column 列配置（未使用，保持 formatter 签名一致）
 * @param {any} cellValue 单元格原值（position/address），作为兜底
 * @returns {string}
 */
export const housePositionFormatter = (row, column, cellValue) => {
  if (!row) return cellValue == null ? '' : String(cellValue)
  const has = (v) => v !== null && v !== undefined && v !== ''
  const projectName = has(row.projectName) ? row.projectName : ''
  const buildingNo = has(row.buildingNo) ? row.buildingNo : ''
  const unitName = has(row.unitName) ? row.unitName : ''
  const houseNo = has(row.houseNo) ? row.houseNo : ''

  // 项目名与幢号直接相连（隆舜园3），其后单元/室号各以 - 连接
  const segments = []
  const head = `${projectName}${buildingNo}`
  if (head !== '') segments.push(head)
  if (unitName !== '') segments.push(unitName)
  if (houseNo !== '') segments.push(houseNo)

  const result = segments.join('-')
  // 行字段全空时回退到后端拼接串，避免显示为空
  return result !== '' ? result : cellValue == null ? '' : String(cellValue)
}

export default housePositionFormatter

